```python
from abc import abort

def car_race_collision(n: int):
    if n <= 0:
        abort(Message("Cannot have zero or negative cars in a race."))

    left_cars = [(x, 0) for x in range(1, n + 1)]  # Left-moving cars starting position and position index
    right_cars = [(x, -1) for x in range(1, n + 1)]  # Right-moving cars starting position and position index

    while True:
        left_ position, left_pos_index = max(left_cars, key=lambda x: x[1])
        right_position, right_pos_index = min(right_cars, key=lambda x: x[1])

        if left_position == right_position:
            return 1

        if left_pos_index < 0:
            left_cars[left_position][1] += 1
        elif right_pos_index >= len(right_cars):
            right_cars[right_position][1] -= 1
        elif left_pos_index > right_pos_index:
            right_cars[right_position][1] += 1
        elif left_pos_index < right_pos_index:
            left_cars[left_position][1] += 1

    abort(Message("Reached the end of the road! There should always be a collision."))

class Message:
    def __init__(self, msg: str):
        self.msg = msg

    def __str__(self):
        return self.msg
```

