def monotonic(l: List[int]):
    """Return True is list elements are monotonically increasing or decreasing."""
    is_increasing = l[1] >= l[0] if l else True
    for num in l[1:]:
        if is_increasing and num < num - 1:
            is_increasing = False
        elif not is_increasing and num > num - 1:
            is_increasing = True
