from collections import deque

def match_parens(lst):
    stack = deque()
    for s in lst:
        for open_paren in s:
            if open_paren == '(':
                stack.append(open_paren)
            elif open_paren == ')':
                if stack:
                    stack.pop()
                else:
                    return 'No'
    return 'Yes' if not stack else 'No'
```

